// The Episode registry (GLOSSARY): what `npm run episodes:registry` writes from the Episode folders. An Episode is its
// folder, `src/components/episodes/<slug>/`, so the slug list, the store's metadata records and the compositions are
// derived from the folders, one generated file per tier (FE-007: lib may not import the store or a component). Each file is checked in, so `tsc` reads the records where they are written, and a fast test fails
// when one is stale. The disk side lives in episode-registry.ts.

/** One folder under `src/components/episodes/`: its name, its entries, and its `episode.ts` text when it has one. */
export interface EpisodeFolder {
  readonly slug: string;
  readonly files: readonly string[];
  readonly episodeSource?: string;
}

/** One generated file: its path from the repository root, and its whole text. */
export interface RegistryFile {
  readonly path: string;
  readonly text: string;
}

/** Where each tier's registry lives. */
export const REGISTRY_PATHS = {
  slugs: 'src/lib/episode-registry.generated.ts',
  metadata: 'src/content-store/episode-registry.generated.ts',
  compositions: 'src/components/episodes/episode-registry.generated.ts',
} as const;

const METADATA_FILE = 'episode-metadata.ts';
const RECORD_FILE = 'episode.ts';
const HEADER = [
  '// The Episode registry, generated by `npm run episodes:registry` from the Episode folders: never edit by hand. A',
  '// folder `src/components/episodes/<slug>/` holding `episode-metadata.ts` is an Episode; with `episode.ts`, a page.',
].join('\n');
const SLUG_TYPE = "import type { EpisodeSlug } from '@/lib/routes';";

/** An Episode with a page: its slug, the identifier it is imported under, and the name its `episode.ts` exports. */
interface RegisteredEpisode {
  readonly slug: string;
  readonly local: string;
  readonly exported: string;
}

/** The identifier a slug is imported under: `ai-token-economy` → `aiTokenEconomy`. */
function identifierOf(slug: string): string {
  const camel = slug.replace(/-([a-z0-9])/g, (_, next: string) => next.toUpperCase());
  return /^[0-9]/.test(camel) ? `_${camel}` : camel;
}

/** The one Episode record an `episode.ts` exports, as `export const <name> = episode({`. */
function exportedRecord(folder: EpisodeFolder): string {
  const names = [...(folder.episodeSource ?? '').matchAll(/export const (\w+)\s*=\s*episode\(/g)].map(
    ([, name]) => name,
  );
  if (names.length !== 1)
    throw new Error(
      `${folder.slug}/${RECORD_FILE} must export exactly one Episode record, \`export const <name> = episode({…})\`; found ${names.length}`,
    );
  return names[0];
}

function importOf({ local, exported }: RegisteredEpisode, from: string): string {
  return `import { ${exported === local ? local : `${exported} as ${local}`} } from '${from}';`;
}

function slugsFile(episodes: readonly RegisteredEpisode[]): string {
  const slugs = episodes.map(({ slug }) => `'${slug}'`).join(', ');
  return `${HEADER}

/** Every Episode with a page, public or unlisted, by folder name. */
export const EPISODE_SLUGS = [${slugs}] as const;
`;
}

function metadataFile(episodes: readonly RegisteredEpisode[], upcoming: readonly string[]): string {
  const asMetadata = (slug: string) => ({ slug, local: identifierOf(slug), exported: 'episodeMetadata' });
  const imports = [...episodes.map(({ slug }) => asMetadata(slug)), ...upcoming.map(asMetadata)]
    .sort((a, b) => a.slug.localeCompare(b.slug))
    .map((each) => importOf(each, `@/components/episodes/${each.slug}/episode-metadata`));
  return `${HEADER}
${SLUG_TYPE}
import type { EpisodeInput } from './schemas/episode.schema';
${imports.join('\n')}

/** Every Episode with a page, public or unlisted: its metadata by slug, so a key and its record's slug must match. */
export const EPISODE_METADATA = {
${episodes.map(({ slug, local }) => `  '${slug}': ${local},`).join('\n')}
} as const satisfies { readonly [S in EpisodeSlug]: EpisodeInput & { readonly slug: S } };

/** Upcoming Episodes without a page, by folder name: each folder holding only its metadata. */
export const UPCOMING_METADATA: readonly EpisodeInput[] = [${upcoming.map(identifierOf).join(', ')}];
`;
}

function compositionsFile(episodes: readonly RegisteredEpisode[]): string {
  return `${HEADER}
import type { EpisodeComposition } from '@/components/slide-master/slide';
${SLUG_TYPE}
${episodes.map((each) => importOf(each, `./${each.slug}/episode`)).join('\n')}

/** Every Episode's composition by slug, so a key and its record's slug must match. */
export const EPISODES: { readonly [S in EpisodeSlug]: EpisodeComposition & { readonly slug: S } } = {
${episodes.map(({ slug, local }) => `  '${slug}': ${local},`).join('\n')}
};
`;
}

/**
 * The three registry files for the given folders. A folder without `episode-metadata.ts` is no Episode (a tooling page)
 * and is left out; one with metadata but no `episode.ts` is an upcoming Episode without a page. Order is folder name.
 */
export function episodeRegistryFiles(folders: readonly EpisodeFolder[]): readonly RegistryFile[] {
  const sorted = folders
    .filter(({ files }) => files.includes(METADATA_FILE))
    .sort((a, b) => a.slug.localeCompare(b.slug));
  const episodes = sorted
    .filter(({ files }) => files.includes(RECORD_FILE))
    .map((folder) => ({ slug: folder.slug, local: identifierOf(folder.slug), exported: exportedRecord(folder) }));
  const upcoming = sorted.filter(({ files }) => !files.includes(RECORD_FILE)).map(({ slug }) => slug);
  return [
    { path: REGISTRY_PATHS.slugs, text: slugsFile(episodes) },
    { path: REGISTRY_PATHS.metadata, text: metadataFile(episodes, upcoming) },
    { path: REGISTRY_PATHS.compositions, text: compositionsFile(episodes) },
  ];
}
